ee:variables.ee:set-variable:
%dw 2.0
output application/json
fun segments(p) = (p default '') splitBy '/' filter ((s) -> s != '')
fun isParam(seg) = startsWith(seg, '{') and endsWith(seg, '}')
fun segMatches(tSeg, aSeg) = isParam(tSeg) or (tSeg == aSeg)
var actualSegs = segments(vars.mockPath)
fun templateMatches(template) = do {
    var tSegs = segments(template)
    ---
    (sizeOf(tSegs) == sizeOf(actualSegs)) and isEmpty(tSegs filter ((seg, idx) -> !segMatches(seg, actualSegs[idx])))
}
fun specificity(template) = sizeOf(segments(template) filter ((seg) -> !isParam(seg)))
var candidates = (vars.candidateRows default []) filter ((r) -> templateMatches(r.path))
var ranked = candidates orderBy ((c) -> specificity(c.path) * -1)
---
ranked[0]
